head.script:
scwin.onpageload = function() {
    var rowJSON = [
        {
            "col1": "A",
            "col2": "B",
            "col3": "C"
        },
        {
            "col1": "11",
            "col2": "22",
            "col3": "33"
        },
        {
            "col1": "XX",
            "col2": "YY",
            "col3": "ZZ"
        }
    ];
    var src = location.href.toString();
    if (src.indexOf("127.0.0.1") >= 0) {
        src = src.replace("127.0.0.1", "localhost");
    } else if (src.indexOf("localhost") >= 0) {
        src = src.replace("localhost", "127.0.0.1");
    }
    src = src.replace("windowContainer_iframe_chrome122_WESD-1727_(WSQ-5776)_main.xml", "windowContainer_iframe_chrome122_WESD-1727_(WSQ-5776)_sub.xml")
    var ff = 0
    var options = {
        title: "music",
        src: src,
        windowTitle: "music",
        windowId: "music",
        openAction: "existWindow",
        frameMode: "iframe",
        dataObject: {
            type: "json",
            name: "paramData",
            data: rowJSON
        }
    }
    windowContainer1.createWindow(options);

    var options2 = {
        title: "art",
        src: src,
        windowTitle: "art",
        windowId: "art",
        openAction: "existWindow",
        frameMode: "iframe",
        dataObject: {
            type: "json",
            name: "paramData",
            data: rowJSON
        }
    }
    windowContainer1.createWindow(options2);
    windowContainer1.doVerticalArrange();

    dataList1.setJSON(rowJSON);
}

scwin.windowContainer1_onwindowmousedown = function(e) {
    console.log("windowContainer1_onwindowmousedown", e)
}

scwin.windowContainer1_onwindowkeyup = function(e) {
    console.log("windowContainer1_onwindowkeyup", e.keyCode)
}


function fn_closeMsg() {
    return confirm("do you close this window?"); // 확인, 취소 버튼이 있는 메세지 창 사용. 
    //return false; // 무조건 닫기 취소.
}
